class open_digraph(open_digraph_display_mx, open_digraph_connectivite_mx, open_digraph_tritopo_mx, node): # for open directed graph

    def __init__(self, inputs, outputs, nodes):
        '''
        inputs: int list; the ids of the input nodes
        outputs: int list; the ids of the output nodes
        nodes: node list;
        '''
        self.inputs = inputs
        self.outputs = outputs
        self.nodes = {node.id:node for node in nodes} # self.nodes: <int,node> dict

    def __str__ (self):
        return "inputs: " + str(self.inputs) + "\n" + "outputs: "+ str(self.outputs) + "\n" + "nodes: " + str(self.nodes)

    @classmethod
    def empty(cls):
        return cls([],[],[])

    def copy(self):
        newNodes = {}
        d = open_digraph.empty()
        d.inputs = self.inputs.copy()
        d.outputs = self.outputs.copy()
        for key in self.nodes.keys():
            n0 = node(-1, '', {}, {})
            n0.id = self.nodes[key].id
            n0.label = self.nodes[key].label
            n0.parents = self.nodes[key].parents.copy()
            n0.children = self.nodes[key].children.copy()
            newNodes[key]=n0
        d.nodes = newNodes
        return d
    #ok

    def get_input_ids(self):
        return self.inputs
        #return [i.get_id() for i in self.inputs] 
    #ok

    def get_output_ids(self):
        return self.outputs
