    #ok

    def get_node_by_id(self, i):
        '''
        i : int (id of the node)
        '''
        return self.nodes[i]
    #ok

    def get_nodes_by_ids(self, t):
        '''
        t : int iter
        '''
        return [self.nodes[i] for i in t]
    #ok

    def get_input_nodes(self):
        return [self.nodes[node_id] for node_id in self.inputs]

    def get_output_nodes(self):
        return [node for node in self.nodes.values() if node.outdegree() == 0 and node in self.outputs]

    def set_input_ids(self, t):
        '''
        t : int list
        '''
        self.inputs = t
    #ok

    def set_output_ids(self, t):
        '''
        t : int list
        '''
        self.outputs = t
    #ok

    def add_node(self, label='', parents=None, children=None): #parents et children sont des dictionnaires
        '''
        adds a NEW (it creates it !) a node
        label : string
        parents : int:int dict
        children : int:int dict
        '''
        if parents is None:
            parents = {}
        if children is None:
            children = {}
        new_id = self.new_id()
        new_node = node(new_id, label, parents, children)
        self.nodes[new_id] = new_node
        for parent_id in parents:
            self.nodes[parent_id].children[new_id] = parents[parent_id]
        for child_id in children:
            self.nodes[child_id].parents[new_id] = children[child_id]
        return new_id
    #ok

    def add_input_node (self, id):
        nid = self.new_id()
        if (id in self.get_input_ids()) or (id in self.get_output_ids()):
            raise  "invalid connection"
        else:
            self.nodes[nid] = node(nid, "input", dict(), {id:1})
            self.nodes[id].parents[nid] = 1
            self.add_input_id(nid)
    #ok

    def add_output_node (self, id):
        nid = self.new_id()
        if (id in self.get_input_ids()) or (id in self.get_output_ids()):
            raise  "invalid connection"
        else:
            self.nodes[nid] = node(nid,"output",{id:1},dict())
            self.nodes[id].children[nid] = 1
            self.add_output_id(nid)
    #ok

    def add_input_id(self, t):
        '''
        makes an existing node an input
        t : int (id of the node)
        '''
        if t in self.inputs:
            raise "Already an input"
        else:
            self.inputs += [t]
    #ok

    def add_output_id(self, t):
        '''
        makes an existing node an output
        t : int (id of the node)
        '''
        if t in self.outputs:
            raise 'Already an output'
        else:
            self.outputs += [t]
    #ok

    def add_edge(self, src, tgt):
        if src not in self.nodes:
            raise ValueError(f"node id source invalide :{src}")  #vérifie si le noeud source (src) existe dans la liste des noeuds (nodes) de ce graph
        if tgt not in self.nodes:
            raise ValueError(f"node id cible invalide :{tgt}") #vérifie si le noeud cible (tgt) existe dans la liste des noeuds (nodes)

        src_node = self.get_node_by_id(src) # récupere le noeud source a partir de la liste de neouds en utilisant l'identifiant src du noeud source
        tgt_node = self.get_node_by_id(tgt) # recupere le noeud cible a partir de la liste des noeuds en utilisant l'id tgt du noeud cible
        src_node.add_child_id(tgt)
        tgt_node.add_parent_id(src)
    #ok

    def add_edges(self, edges):
        '''
        edges : (int, int) iter
        '''
        for src, tgt in edges:
         self.add_edge(src, tgt)
    #ok

